public class Main {
    public static void main(String[] args) {
        String str = null;

        try {
            int len = str.length();
            System.out.println("len = " + len);
        } catch (NullPointerException e) {
            System.out.println("len check: NPE");
        }

        String text = null;
        try {
            boolean result = text.equals("hello");
            System.out.println("result = " + result);
        } catch (NullPointerException e) {
            System.out.println("result check: NPE");
        }

        boolean safe = "hello".equals(text);
        System.out.println("safe = " + safe);
    }
}
